package app.rwun;
import android.content.Context;import org.json.*;import java.util.*;import java.time.*;import java.nio.file.*;import java.io.*;
public final class FocusHostTest {
 static int n;static void ok(boolean v,String label){n++;if(!v)throw new AssertionError(label);}interface Work{void run()throws Exception;}static void bad(Work w,String s){boolean fail=false;try{w.run();}catch(Exception e){fail=true;}ok(fail,s);}
 static JSONObject archivedRide(String id)throws Exception{return new JSONObject().put("id",id).put("date",LocalDate.now().toString()).put("kind","Road").put("km",40).put("seconds",7200).put("source","GPS").put("route","route-retired.jsonl").put("hr",140).put("effort",8).put("fatigue",2).put("pain",false);}
 public static void main(String[] args)throws Exception{Context c=new Context(Files.createTempDirectory("rwun-focus").toFile());RunStore s=new RunStore(c);s.save(new PlanEngine.Config(8,3,12,5,LocalDate.now()));s.completeStrength("foundation");JSONObject gym=new JSONObject().put("id","old-gym").put("date",LocalDate.now().toString()).put("type","Gym").put("minutes",60).put("effort",9).put("completed",false);s.v1(new JSONObject().put("activities",new JSONArray().put(gym)));JSONObject cycle=new JSONObject().put("rides",new JSONArray().put(archivedRide("old-ride"))).put("planned",new JSONArray().put(new JSONObject().put("id","ride-plan").put("date",LocalDate.now().toString()).put("kind","Road").put("minutes",120).put("effort",9)));JSONObject active=new JSONObject().put("id","old-indoor").put("date",LocalDate.now().toString()).put("kind","Indoor");V103Data.clock(active,new IndoorClock(30,1000,1,false,false));cycle.put("active",active);s.cycling(cycle,false,false);try(var out=c.openFileOutput("route-retired.jsonl",0)){out.write("{\"lat\":0,\"lon\":0,\"time\":1000}\n".getBytes());}s.checkpoint(new JSONObject().put("id","ride:pending").put("cycling",true).put("date",LocalDate.now().toString()).put("seconds",0).put("km",0).put("route","route-not-created.jsonl").toString());s.refocus(c);ok(s.strengthSessions().length()==1&&V1State.activities(s.v1()).size()==1,"legacy gym/strength data preserved");ok(s.cycling().getJSONArray("rides").length()==1&&s.cycling().getJSONArray("planned").length()==1,"legacy cycling data preserved");ok(s.otherActivities().isEmpty(),"retired data does not influence running schedule");ok(s.checkpoint().isEmpty()&&!s.indoorPending(),"retired recordings no longer block core app");ok(s.cycling().getJSONArray("archivedRecordings").length()==2,"both unfinished records archived");JSONObject pending=s.cycling().getJSONArray("archivedRecordings").getJSONObject(1);ok(pending.getLong("seconds")==0&&pending.getDouble("km")==0,"no invented recovery metrics");ok(pending.getString("route").isEmpty()&&pending.has("missingRoute"),"missing route safely recorded as missing");s.refocus(c);ok(s.cycling().getJSONArray("archivedRecordings").length()==2,"migration idempotent");String fingerprint=s.proposalFingerprint();s.cycling(new JSONObject(s.cycling().toString()).put("planned",new JSONArray()),false,false);ok(fingerprint.equals(s.proposalFingerprint()),"archived plans cannot invalidate live running preview");
  s.addWalk(new RunStore.Run("walk:one",LocalDate.now().toString(),2,30,4,2,false,"GPS","",0,1800));ok(s.walks().length()==1&&s.runs().isEmpty(),"GPS walk never creates running mileage");ok(s.completed("walk:one"),"walking recovery identifies saved record");bad(()->s.addWalk(new RunStore.Run("walk:one",LocalDate.now().toString(),2,30)),"duplicate walking save rejected");s.addWalk(new RunStore.Run("walk:health:one",LocalDate.now().toString(),0,10,0,2,false,"Health Connect · source","",0,600));ok(!s.walks().getJSONObject(1).getBoolean("distanceKnown"),"missing imported distance remains time only");WalkData.Week w=WalkData.week(s.v103(),LocalDate.now());ok(w.seconds()==2400&&w.km()==2&&w.days()==1&&w.sessions()==2,"walking summary uses actual values");s.deleteWalk("walk:one");ok(!s.completed("walk:one")&&s.v103().has("walkUndo"),"walking soft deletion");s.undoWalk();ok(s.walks().length()==2&&s.completed("walk:one"),"walking undo restores identity");bad(()->s.addWalk(new RunStore.Run("walk:bad",LocalDate.now().toString(),-1,30)),"invalid walk distance rejected");bad(()->s.addWalk(new RunStore.Run("run:wrong",LocalDate.now().toString(),2,30)),"non-walk identity rejected");
  String file="route-walk.jsonl";try(var out=c.openFileOutput(file,0)){out.write("{\"lat\":0,\"lon\":0,\"time\":1000}\n".getBytes());}s.addWalk(new RunStore.Run("walk:route",LocalDate.now().toString(),1,10,3,2,false,"GPS",file,0,600));ByteArrayOutputStream bytes=new ByteArrayOutputStream();BackupManager.exportTo(c,s,bytes);Context target=new Context(Files.createTempDirectory("rwun-focus-restore").toFile());RunStore restored=new RunStore(target);BackupManager.restoreFrom(target,restored,new ByteArrayInputStream(bytes.toByteArray()));ok(restored.walks().length()==3&&restored.runs().isEmpty(),"backup restores walking separately");String walkFile=restored.walks().getJSONObject(2).getString("route"),oldCycle=restored.cycling().getJSONArray("rides").getJSONObject(0).getString("route");ok(!walkFile.equals(file)&&target.getFileStreamPath(walkFile).exists(),"walking route remapped and preserved");ok(target.getFileStreamPath(oldCycle).exists(),"legacy cycling route preserved in backup");ok(restored.strengthSessions().length()==1,"legacy strength preserved through backup");
  s.addWalk(new RunStore.Run("walk:pain",LocalDate.now().toString(),1,15,5,3,true,"GPS","",0,900));ok(s.resting(),"walk pain keeps training hold");s.refocus(c);ok(s.resting(),"scope migration does not clear holds");String runCheckpoint=new JSONObject().put("id","free:pending").put("seconds",20).toString();Context fresh=new Context(Files.createTempDirectory("rwun-focus-run").toFile());RunStore r=new RunStore(fresh);r.checkpoint(runCheckpoint);r.refocus(fresh);ok(r.checkpoint().equals(runCheckpoint),"unfinished running session remains recoverable");
  JSONObject mixed=s.v103();JSONArray indoors=new JSONArray();indoors.put(new JSONObject().put("id","indoor-walk").put("kind","Walk").put("date",LocalDate.now().toString()).put("seconds",600).put("km",JSONObject.NULL).put("effort",3).put("fatigue",2).put("pain",false));indoors.put(new JSONObject().put("id","indoor-run").put("kind","Run").put("date",LocalDate.now().toString()).put("seconds",900).put("km",2).put("effort",4).put("fatigue",2).put("pain",false));mixed.put("indoor",indoors);s.v103(mixed);ok(WalkData.all(mixed).size()==s.walks().length()+1,"indoor runs never appear in walking history");ok(WalkData.week(mixed,LocalDate.now()).seconds()==WalkData.week(s.v103(),LocalDate.now()).seconds(),"unified walking summaries consistent");
  Context old=new Context(Files.createTempDirectory("rwun-old-route").toFile());RunStore legacy=new RunStore(old);try(var out=old.openFileOutput("route-pending-cycle.jsonl",0)){out.write("{\"lat\":0,\"lon\":0,\"time\":1000}\n".getBytes());}legacy.checkpoint(new JSONObject().put("id","old-pending").put("cycling",true).put("seconds",30).put("route","route-pending-cycle.jsonl").toString());legacy.refocus(old);ByteArrayOutputStream raw=new ByteArrayOutputStream();BackupManager.exportTo(old,legacy,raw);Context next=new Context(Files.createTempDirectory("rwun-old-route-restored").toFile());RunStore last=new RunStore(next);BackupManager.restoreFrom(next,last,new ByteArrayInputStream(raw.toByteArray()));String archived=last.cycling().getJSONArray("archivedRecordings").getJSONObject(0).getString("route");ok(!archived.equals("route-pending-cycle.jsonl")&&next.getFileStreamPath(archived).isFile(),"unfinished archived route bytes survive backup and remapping");JSONObject invalid=s.backupPreferences().put("focusVersion",2);bad(()->RunStore.validatePreferences(invalid),"unknown migration version rejected");
  Context correctionContext=new Context(Files.createTempDirectory("rwun-walk-correction").toFile());RunStore correction=new RunStore(correctionContext);
  correction.addWalk(new RunStore.Run("walk:missed",LocalDate.now().toString(),0,30,4,2,false,"GPS","",0,1800));
  ok(!correction.walks().getJSONObject(0).getBoolean("distanceKnown"),"zero GPS distance is time only, not a measured walk");
  correction.correctWalkDistance("walk:missed",2);var corrected=new RunStore(correctionContext).walks().getJSONObject(0);
  ok(corrected.getDouble("km")==2&&corrected.getLong("seconds")==1800&&corrected.getString("source").equals("Manual walk distance")&&corrected.getString("recordedSource").equals("GPS"),"known 2 km corrects distance while preserving time and source provenance");
  ok(correction.runs().isEmpty()&&corrected.getString("route").isEmpty(),"manual walk correction invents neither GPS route nor running mileage");
  bad(()->correction.correctWalkDistance("walk:missed",Double.NaN),"invalid correction rejected");
  ok(correction.walks().getJSONObject(0).getDouble("km")==2,"invalid edit keeps corrected distance");
  System.out.println(n+" scope/walking/migration assertions passed");
 }
}
